<script setup lang="ts">
import FieldError from './FieldError.vue'
import type {FieldErrors} from '../validation'
defineProps<{items:any[],busy:boolean,prefix:string,errors:FieldErrors}>()
const emit=defineEmits<{quantity:[index:number,value:number],remove:[index:number]}>()
</script>
<template><div class="queue-empty" v-if="!items.length"><span class="empty-symbol">＋</span><b>还没有添加物品</b><p>{{prefix==='mail'?'从列表加入物品、使用礼包，或在下方填写金币。':'从物品列表加入附件，或使用已有礼包。'}}</p></div><ol class="item-queue" v-else><li v-for="(i,n) in items" :key="n"><div class="item-title"><span class="item-number">{{n+1}}</span><div><b>{{i.name||'物品'}}</b><small>#{{i.id}} · {{i.category==='equipment'?'装备':i.category==='material'?'材料':'消耗品'}} · {{i.quantity_unlimited?'策略不限量 · 数量字段最大2147483647':'上限 '+(i.category==='equipment'?1:i.stack_limit||'未知')}}</small></div><button class="icon-button ghost" :disabled="busy" :aria-label="'移除物品 '+i.id+' 第'+(n+1)+'条'" @click="emit('remove',n)">×</button></div><label class="quantity-row">数量<input :id="prefix+'-quantity-'+n" :aria-invalid="!!errors[prefix+'-quantity-'+n]" :aria-describedby="errors[prefix+'-quantity-'+n]?prefix+'-quantity-'+n+'-error':undefined" type="number" min="1" :max="i.category==='equipment'?1:i.stack_limit||1000000" :value="i.quantity" :aria-label="'物品数量 '+i.id" :disabled="busy||i.category==='equipment'" @input="emit('quantity',n,Number(($event.target as HTMLInputElement).value))"></label><FieldError :id="prefix+'-quantity-'+n+'-error'" :message="errors[prefix+'-quantity-'+n]"/></li></ol></template>
